// ================================================================
//  5. GAME LOGIC  (you normally don't need to edit below)
// ================================================================
var ASTEROID_SPAWN_INTERVAL = Math.max(1, Math.round(60 / ASTEROIDS_PER_SECOND));

// Aliens per second for the given wave (index 0 = wave 1), taken from WAVES[...].spawnRate
function alienSpawnRate(waveIndex) {
  var w = WAVES[Math.min(waveIndex, WAVES.length - 1)];
  return (w && w.spawnRate > 0) ? w.spawnRate : 1;
}

function log(msg) { if (typeof echo === "function") { echo(msg); } }

// ---------- helpers ----------
function expandGroup(group) {
  var list = [];
  for (var key in group) {
    for (var i = 0; i < group[key]; i++) { list.push(key); }
  }
  return list;
}

function shuffle(arr) {
  for (var i = arr.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var t = arr[i]; arr[i] = arr[j]; arr[j] = t;
  }
  return arr;
}

function randomEdgePosition(game) {
  var R = game.options.map_size * 5 * 0.8;
  var ang = Math.random() * Math.PI * 2;
  return { x: Math.cos(ang) * R, y: Math.sin(ang) * R };
}

// ---------- narrator messages that disappear on their own ----------
function say(game, text, duration) {
  var g = game.custom;
  for (var i = 0; i < game.ships.length; i++) {
    var s = game.ships[i];
    s.showInstructor();
    s.instructorSays(text, MESSAGE_CHARACTER);
  }
  g.hideAt = game.step + (duration || MESSAGE_DURATION);
}

function hideMessages(game) {
  for (var i = 0; i < game.ships.length; i++) {
    game.ships[i].hideInstructor();
  }
  game.custom.hideAt = null;
}

// ---------- narrator text helpers ----------
function fillText(template, vars) {
  return String(template).replace(/\{(\w+)\}/g, function (m, k) { return vars[k] !== undefined ? vars[k] : m; });
}

function countGroup(group) {
  var n = 0;
  for (var k in group) { n += group[k]; }
  return n;
}

function plural(n, one, many) { return n + " " + (n === 1 ? one : many); }

// 120 -> "2 minutes", 90 -> "1 minute and 30 seconds", 45 -> "45 seconds"
function formatDuration(seconds) {
  var m = Math.floor(seconds / 60), r = Math.round(seconds % 60), parts = [];
  if (m > 0) { parts.push(plural(m, "minute", "minutes")); }
  if (r > 0 || m === 0) { parts.push(plural(r, "second", "seconds")); }
  return parts.join(" and ");
}

// "20 aliens" / "24 aliens and 1 boss" / "3 bosses" - always counted from the wave's own lists
function describeWave(waveIndex) {
  var w = WAVES[waveIndex], parts = [];
  var aliens = countGroup(w.minions), bosses = countGroup(w.bosses);
  if (aliens > 0) { parts.push(plural(aliens, "alien", "aliens")); }
  if (bosses > 0) { parts.push(plural(bosses, "boss", "bosses")); }
  return parts.length ? parts.join(" and ") : "no enemies";
}

function showVictoryScreen(game) {
  for (var i = 0; i < game.ships.length; i++) {
    game.ships[i].gameover({
      "Result": "VICTORY!",
      "Waves cleared": WAVES.length + "/" + WAVES.length,
      "Score": game.ships[i].score
    });
  }
}

// ---------- config check (prints warnings in the console) ----------
function validateConfig() {
  for (var w = 0; w < WAVES.length; w++) {
    var wave = WAVES[w];
    if (!(wave.spawnRate > 0)) { log("CONFIG ERROR wave " + (w + 1) + ": spawnRate must be a number > 0"); }
    var groups = [["minions", wave.minions, false], ["bosses", wave.bosses, true]];
    var bossCount = 0;
    for (var gi = 0; gi < groups.length; gi++) {
      var name = groups[gi][0], group = groups[gi][1], isBossGroup = groups[gi][2];
      for (var key in group) {
        var a = ALIENS[key];
        if (!a) { log("CONFIG ERROR wave " + (w + 1) + ": unknown alien '" + key + "'"); continue; }
        if (!DROPS[key]) { log("CONFIG WARNING: no DROPS entry for '" + key + "'"); }
        if (!COMBAT_DROPS[key]) { log("CONFIG WARNING: no COMBAT_DROPS entry for '" + key + "'"); }
        if (isBossGroup) { bossCount += group[key]; }
        if (a.hp !== null) {
          if (!isBossGroup && a.hp >= BOSS_HP_THRESHOLD) {
            log("CONFIG WARNING wave " + (w + 1) + ": '" + key + "' (HP " + a.hp + ") is boss-class but listed as minion");
          }
          if (isBossGroup && a.hp < MINI_BOSS_HP) {
            log("CONFIG WARNING wave " + (w + 1) + ": '" + key + "' (HP " + a.hp + ") is too weak for a boss");
          }
        }
      }
    }
    if (w + 1 < FIRST_BOSS_WAVE && bossCount > 0) {
      log("CONFIG WARNING wave " + (w + 1) + ": has bosses before wave " + FIRST_BOSS_WAVE);
    }
  }
  if (START_DELAY < WELCOME_DURATION + SPEED_DURATION + MESSAGE_DURATION) {
    log("CONFIG WARNING: START_DELAY is shorter than the intro messages (welcome + speed + get ready); wave 1 would cut them off");
  }
  for (var ck in COMBAT_DROPS) {
    var cd = COMBAT_DROPS[ck];
    if (!ALIENS[ck]) { log("CONFIG WARNING: COMBAT_DROPS has unknown alien '" + ck + "'"); }
    if (cd.item !== null && COMBAT_ITEMS[cd.item] === undefined) { log("CONFIG ERROR: COMBAT_DROPS '" + ck + "' has unknown item '" + cd.item + "'"); }
    if (!(cd.percent >= 0 && cd.percent <= 100)) { log("CONFIG ERROR: COMBAT_DROPS '" + ck + "' percent must be 0-100"); }
  }
}

// ---------- spawning ----------
// Randomly rounds to a whole number so that the AVERAGE stays exact (12.5 -> 12 or 13)
function randomRound(x) {
  var f = Math.floor(x);
  return f + (Math.random() < x - f ? 1 : 0);
}

function spawnAlien(game, key, isBoss) {
  var a = ALIENS[key];
  var d = DROPS[key] || { points: 0, crystals: 0 };
  var p = randomEdgePosition(game);
  var opts = {
    x: p.x, y: p.y, vx: 0, vy: 0,
    code: a.code,
    level: a.level,
    points: d.points
  };
  // crystals: bosses drop the base amount, regular aliens x MINION_CRYSTAL_MULTIPLIER
  opts.crystal_drop = isBoss ? d.crystals : randomRound(d.crystals * MINION_CRYSTAL_MULTIPLIER);
  // combat item: decided by the alien TYPE (table COMBAT_DROPS); aliens with item null get no weapon_drop at all
  var c = COMBAT_DROPS[key];
  if (c && c.item && Math.random() * 100 < c.percent) { opts.weapon_drop = COMBAT_ITEMS[c.item]; }
  game.addAlien(opts);
}

function spawnAsteroid(game) {
  var p = randomEdgePosition(game);
  game.addAsteroid({
    x: p.x, y: p.y,
    vx: (Math.random() - 0.5) * 0.8,
    vy: (Math.random() - 0.5) * 0.8,
    size: ASTEROID_SIZE
  });
}

function startWave(game) {
  var g = game.custom;
  var w = WAVES[g.wave];
  g.minionQueue = shuffle(expandGroup(w.minions));
  g.bossQueue = expandGroup(w.bosses);
  g.asteroidsLeft = ASTEROIDS_PER_WAVE * (g.wave + 1);
  g.bossAnnounced = false;     // true = boss phase has started
  g.clearTicks = 0;
  g.spawnAcc = 0;
  g.state = "fighting";
  g.waveTicks = 0;                                       // wave timer restarts at 00:00
  hideMessages(game);                                    // the narrator stays silent while a wave is being fought
  updateUI(game);                                        // show 00:00 / the new wave at once
}

function rewardPlayers(game) {
  var i, x, y;
  for (i = 0; i < WAVE_CLEAR_ENERGY_PACKS; i++) {
    x = (Math.random() - 0.5) * 200; y = (Math.random() - 0.5) * 200;
    game.addCollectible({ code: 90, x: x, y: y });
  }
  for (i = 0; i < WAVE_CLEAR_SHIELD_PACKS; i++) {
    x = (Math.random() - 0.5) * 200; y = (Math.random() - 0.5) * 200;
    game.addCollectible({ code: 91, x: x, y: y });
  }
  if ((game.custom.wave + 1) % 5 === 0) {
    game.addCollectible({ code: 11, x: 20, y: 20 });
    game.addCollectible({ code: 21, x: -20, y: -20 });
  }
}

// ---------- CUSTOM SCOREBOARD (replaces the game's built-in scoreboard on the right) ----------
// There is NO extra panel: a UI component with the id "scoreboard" takes over the built-in
// scoreboard and fills exactly the area the game reserves for it, in its original place.
// It shows: current wave, asteroids, aliens and the score of the players.
// It is sent to every player separately, so each player sees their own row highlighted.
var SCOREBOARD_MAX_ROWS     = 7;      // rows in the player list (last row says "+N more" when there are more players)
var SCOREBOARD_NAME_MAX     = 16;     // longer names are cut (only used when SCOREBOARD_NAME_MODE = "text")
var SCOREBOARD_NAME_MODE    = "player"; // "player" = game's own name + badge   |   "text" = plain text name
var SCOREBOARD_HEADER_PX    = 0;      // 0 = the "Scoreboard  TAB" header stays the game's own.
                                      // If the header disappears after the mod starts, set this to 38:
                                      // the mod will then draw a matching header itself.

var SCOREBOARD_COLORS = {
  headerFill: "rgb(231,195,209)",     // colours sampled from the original scoreboard
  headerText: "#191F14",
  label:      "#E7C3D1",
  muted:      "rgba(231,195,209,0.55)",
  value:      "#FFFFFF",
  score:      "#FFFFFF",
  me:         "rgba(255,150,180,0.26)",  // highlight of your own row
  line:       "rgba(231,195,209,0.35)",
  barTrack:   "rgba(231,195,209,0.18)",
  barFill:    "#E7C3D1",
  alien:      "#FF6B6B",
  asteroid:   "#B7C2C7",
  boss:       "#FF9A6B",
  win:        "#8CF0B8"
};

// Design grid in "design pixels" (about the size of the scoreboard at 1080p). Converted to percentages.
var SCOREBOARD_DW = 383, SCOREBOARD_DH = 385;

// 00:00 format, minutes can go above 59
function formatTimer(ticks) {
  var total = Math.floor(ticks / 60), m = Math.floor(total / 60), sec = total % 60;
  return (m < 10 ? "0" : "") + m + ":" + (sec < 10 ? "0" : "") + sec;
}

function formatNumber(n) {
  return String(Math.round(n || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
}

function scoreboardComponent(game, viewer, ranking) {
  var g = game.custom, C = SCOREBOARD_COLORS, comps = [];
  var HP = SCOREBOARD_HEADER_PX, DW = SCOREBOARD_DW, DH = SCOREBOARD_DH + HP;
  var total = WAVES.length;
  var W = WAVES[Math.min(g.wave, total - 1)];

  function X(px) { return px / DW * 100; }
  function Y(py) { return (py + HP) / DH * 100; }      // content is shifted below the optional header
  function H(ph) { return ph / DH * 100; }
  function box(x, y, w, h, fill) { comps.push({ type: "box", position: [X(x), Y(y), X(w), H(h)], fill: fill }); }
  function text(x, y, w, h, value, color, align) {
    comps.push({ type: "text", position: [X(x), Y(y), X(w), H(h)], value: String(value), color: color, align: align || "left" });
  }
  function dot(x, y, size, color) { comps.push({ type: "round", position: [X(x), Y(y), X(size), H(size)], fill: color }); }

  // ----- numbers -----
  var aliensAlive = game.aliens.length;
  var incoming = (g.minionQueue ? g.minionQueue.length : 0) + (g.bossQueue ? g.bossQueue.length : 0);
  var asteroids = game.asteroids.length;          // moving asteroids (the static ones from the map are not counted)

  var waveText = "Wave " + Math.min(g.wave + 1, total) + " / " + total;
  var status = "", statusColor = C.muted, progress = g.wave / total;
  if (g.state === "won") {
    waveText = "Wave " + total + " / " + total; progress = 1; status = "VICTORY!"; statusColor = C.win;
  } else if (g.state === "fighting") {
    if (g.bossAnnounced) { status = "BOSS FIGHT"; statusColor = C.boss; }
  } else {
    status = "Next wave in " + Math.max(0, Math.ceil((g.timer - game.step) / 60)) + " s";
  }

  var timerText = formatTimer(g.waveTicks || 0);
  var timerColor = g.state === "fighting" ? C.value : C.label;   // dimmed while the timer is stopped

  // ----- optional header (only when SCOREBOARD_HEADER_PX > 0) -----
  if (HP > 0) {
    comps.push({ type: "box", position: [0, 0, 100, HP / DH * 100], fill: C.headerFill });
    comps.push({ type: "text", position: [X(14), 0, X(200), HP / DH * 100], value: "Scoreboard", color: C.headerText, align: "left" });
  }

  // ----- wave -----
  text(14, 8, 200, 32, waveText, C.value, "left");
  text(214, 3, 155, 14, "WAVE TIMER", C.label, "right");
  text(214, 17, 155, 28, timerText, timerColor, "right");
  text(14, 46, 190, 18, g.state === "won" ? "All waves cleared" : W.name, C.muted, "left");
  text(204, 46, 165, 18, status, statusColor, "right");
  box(14, 66, 355, 6, C.barTrack);
  if (progress > 0) { box(14, 66, 355 * progress, 6, C.barFill); }

  // ----- asteroids | aliens -----
  dot(14, 94, 14, C.asteroid);
  text(36, 84, 150, 16, "ASTEROIDS", C.label, "left");
  text(36, 100, 150, 30, asteroids, C.value, "left");

  dot(200, 94, 14, C.alien);
  text(222, 84, 70, 16, "ALIENS", C.label, "left");
  text(284, 86, 85, 14, incoming > 0 ? "+" + incoming + " incoming" : "", C.muted, "right");
  text(222, 100, 147, 30, aliensAlive, C.value, "left");

  // ----- players -----
  box(14, 140, 355, 1.5, C.line);
  text(14, 148, 150, 16, "PLAYERS", C.muted, "left");
  text(219, 148, 150, 16, "SCORE", C.muted, "right");

  var rows = SCOREBOARD_MAX_ROWS;
  var shown = ranking.length > rows ? rows - 1 : ranking.length;
  for (var i = 0; i < shown; i++) {
    var s = ranking[i], y = 170 + i * 30;
    if (s === viewer) { box(4, y - 1, 375, 28, C.me); }
    text(10, y + 2, 30, 24, (i + 1) + ".", C.muted, "left");
    if (SCOREBOARD_NAME_MODE === "player") {
      comps.push({ type: "player", id: s.id, position: [X(42), Y(y + 2), X(205), H(24)], color: C.value });
    } else {
      text(42, y + 2, 205, 24, String(s.name || "Player").substring(0, SCOREBOARD_NAME_MAX), C.value, "left");
    }
    text(249, y + 2, 120, 24, formatNumber(s.score), C.score, "right");
  }
  if (ranking.length > rows) {
    text(10, 170 + shown * 30 + 2, 359, 24, "+" + (ranking.length - shown) + " more players", C.muted, "left");
  }

  // no "position": the scoreboard fills the area the game reserves for it
  return { id: "scoreboard", visible: true, components: comps };
}

function sendScoreboard(game, ship, ranking) {
  if (!game.custom.init) { return; }
  ranking = ranking || game.ships.slice().sort(function (a, b) { return (b.score || 0) - (a.score || 0) || a.id - b.id; });
  ship.setUIComponent(scoreboardComponent(game, ship, ranking));
}

function updateUI(game) {
  if (!game.custom.init) { return; }
  var ranking = game.ships.slice().sort(function (a, b) { return (b.score || 0) - (a.score || 0) || a.id - b.id; });
  for (var i = 0; i < game.ships.length; i++) { sendScoreboard(game, game.ships[i], ranking); }
}

// ---------- main loop ----------
this.tick = function (game) {
  var g = game.custom;

  if (!g.init) {
    g.init = true;
    g.wave = 0;
    g.state = "waiting";
    g.timer = game.step + START_DELAY;
    g.minionQueue = [];
    g.bossQueue = [];
    g.asteroidsLeft = 0;
    g.hideAt = null;
    g.waveTicks = 0;          // length of the current / last wave in ticks (wave timer)
    g.readyAnnounced = false;
    g.speedAnnounced = false;
    g.introStart = null;
    g.gameoverAt = null;
    validateConfig();
  }

  // auto-hide narrator messages
  if (g.hideAt !== null && game.step >= g.hideAt) { hideMessages(game); }

  if (game.step % 30 === 0) { updateUI(game); }
  if (game.step % 10 === 0) { pollDemotions(game); }

  if (g.state === "won") {
    if (g.gameoverAt !== null && game.step >= g.gameoverAt) {
      g.gameoverAt = null;
      showVictoryScreen(game);
    }
    return;
  }

  // pause the countdown while nobody is in the game
  if (game.ships.length === 0) {
    if (g.state === "waiting") { g.timer++; }
    return;
  }

  if (g.state === "waiting") {
    // before wave 1 the narrator says three things, one after another:
    //   welcome (when a player spawns)  ->  the message about speed  ->  "Get ready for Wave 1!"
    if (g.wave === 0) {
      if (g.introStart === null) { g.introStart = game.step; }     // starts when the first player is in the game
      var intro = game.step - g.introStart;
      if (!g.speedAnnounced && intro >= WELCOME_DURATION) {
        g.speedAnnounced = true;
        say(game, fillText(TEXT_SPEED, { time: formatDuration(BOSS_TIME_LIMIT_SECONDS) }), SPEED_DURATION);
      }
      if (!g.readyAnnounced && intro >= WELCOME_DURATION + SPEED_DURATION) {
        g.readyAnnounced = true;
        say(game, fillText(TEXT_FIRST_WAVE, { wave: 1, enemies: describeWave(0) }));
      }
    }
    if (game.step >= g.timer) { startWave(game); }
    return;
  }

  // ----- state: fighting -----
  g.waveTicks++;                                         // wave timer runs only while the wave is being fought

  // BOSS PHASE - the bosses of the wave appear as soon as ONE of these two things is true:
  //   1. every regular alien has been spawned AND none is alive. That includes the small pieces a chicken
  //      or crab splits into; the field must stay clear for BOSS_SPAWN_DELAY ticks, so the short moment
  //      between a parent dying and its pieces showing up can never let a boss slip through.
  //   2. the wave timer reaches BOSS_TIME_LIMIT_SECONDS (2:00) - whatever is still alive at that moment.
  if (!g.bossAnnounced && g.bossQueue.length > 0) {
    if (g.minionQueue.length === 0 && game.aliens.length === 0) { g.clearTicks++; } else { g.clearTicks = 0; }
    if (g.clearTicks >= BOSS_SPAWN_DELAY || g.waveTicks >= BOSS_TIME_LIMIT_SECONDS * 60) {
      g.bossAnnounced = true;                            // boss phase starts
      g.spawnAcc = 1;                                    // first boss appears right away
    }
  }

  // aliens: spawn speed is set per wave (spawnRate). In the boss phase the bosses come first,
  // then any regular aliens that are still waiting to spawn (only possible when the time limit started the phase).
  g.spawnAcc = Math.min(3, (g.spawnAcc || 0) + alienSpawnRate(g.wave) / 60);
  while (g.spawnAcc >= 1) {
    if (game.aliens.length >= MAX_ALIENS_ALIVE) { g.spawnAcc = 1; break; }   // field is full, wait
    if (g.bossAnnounced && g.bossQueue.length > 0) {
      spawnAlien(game, g.bossQueue.shift(), true);
      g.spawnAcc -= 1;
    } else if (g.minionQueue.length > 0) {
      spawnAlien(game, g.minionQueue.shift(), false);
      g.spawnAcc -= 1;
    } else {
      g.spawnAcc = 0;                                    // nothing to spawn right now (bosses are waiting for their phase)
      break;
    }
  }

  // asteroids: up to ASTEROIDS_PER_SECOND per second
  if (game.step % ASTEROID_SPAWN_INTERVAL === 0 && g.asteroidsLeft > 0 &&
      game.asteroids.length < MAX_ASTEROIDS_ALIVE) {
    spawnAsteroid(game);
    g.asteroidsLeft--;
  }

  // wave cleared = everything spawned AND every alien dead (asteroids don't matter)
  if (g.minionQueue.length === 0 && g.bossQueue.length === 0 && game.aliens.length === 0) {
    rewardPlayers(game);
    if (g.wave >= WAVES.length - 1) {
      g.state = "won";                                   // wave timer stays frozen on the last wave's time
      say(game, fillText(TEXT_VICTORY, { waves: WAVES.length }), VICTORY_GAMEOVER_DELAY > 0 ? VICTORY_GAMEOVER_DELAY : MESSAGE_DURATION);
      g.gameoverAt = game.step + VICTORY_GAMEOVER_DELAY;
    } else {
      // congratulate and announce the NEXT wave, counted from the config of that wave
      say(game, fillText(TEXT_WAVE_CLEARED, { cleared: g.wave + 1, next: g.wave + 2, enemies: describeWave(g.wave + 1) }));
      g.wave++;
      g.state = "waiting";
      g.timer = game.step + WAVE_DELAY;
    }
    updateUI(game);                                      // show the frozen wave time at once
  }
};

// ---------- GAME OVER when a player would be sent back to a lower ship level ----------
// The game does not tell the mod how many lives a player has left, but it does show the ship type:
// the mod remembers the ship level at death and compares it with the level the player respawns with.
// A lower level = the lives are used up = GAME OVER screen instead of a demotion.
// (A level-1 ship cannot be demoted any further, so for it the game simply continues.)
function shipTier(ship) { return Math.floor((ship.type || 0) / 100); }

function showGameOver(game, ship) {
  ship.custom.tierAtDeath = null;
  ship.custom.respawnedAt = null;
  ship.gameover({
    "Result": "GAME OVER",
    "Reason": "Out of lives",
    "Wave reached": Math.min(game.custom.wave + 1, WAVES.length) + "/" + WAVES.length,
    "Score": ship.score
  });
}

function checkDemotion(game, ship) {
  if (!GAMEOVER_ON_DEMOTION || ship.custom.tierAtDeath == null) { return false; }
  if (shipTier(ship) < ship.custom.tierAtDeath) { showGameOver(game, ship); return true; }
  return false;
}

// every 10 ticks: the ship type may be updated a moment after the respawn event, so look again for 3 seconds
function pollDemotions(game) {
  for (var i = 0; i < game.ships.length; i++) {
    var s = game.ships[i];
    if (s.custom.tierAtDeath == null || s.custom.respawnedAt == null) { continue; }
    if (checkDemotion(game, s)) { continue; }
    if (game.step - s.custom.respawnedAt > 180) { s.custom.tierAtDeath = null; s.custom.respawnedAt = null; }
  }
}

// ---------- events ----------
this.event = function (event, game) {
  switch (event.name) {
    case "ship_destroyed":
      if (event.ship != null) { event.ship.custom.tierAtDeath = shipTier(event.ship); event.ship.custom.respawnedAt = null; }
      break;

    case "ship_spawned":
      if (event.ship != null && event.ship.custom.tierAtDeath != null) {
        if (checkDemotion(game, event.ship)) { break; }              // demoted -> GAME OVER
        event.ship.custom.respawnedAt = game.step;                   // not demoted (yet): keep watching for a moment
      }
      if (event.ship != null) { sendScoreboard(game, event.ship); }
      if (event.ship != null && !event.ship.custom.welcomed && game.custom.state !== "fighting") {
        event.ship.custom.welcomed = true;
        event.ship.showInstructor();
        event.ship.instructorSays(fillText(TEXT_WELCOME, { waves: WAVES.length }), MESSAGE_CHARACTER);
        game.custom.hideAt = Math.max(game.custom.hideAt || 0, game.step + WELCOME_DURATION);
      }
      break;
  }
};
